import unittest,re
from tools.kjv_archive import load_register,read
class JohnWordWitnessTests(unittest.TestCase):
 def test_word_and_witnessing_selves(self):
  prior,_=load_register('0.10-kjv.212');lang,manifest=load_register('0.10-kjv.213')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('john-'):c for c in read(lang.folder/'john-word-and-witnessing-selves-cases.json')};self.assertEqual(len(cases),76)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'1:1': ['kjv_word_john be:pa', 'kjv_word_john with god', 'kjv_word_john god be:pa'], '1:2': ['same in beginning with god'], '1:3': ['all thing:pl by he', 'without he', 'make:psv:neg:pa'], '1:4': ['in he life', 'life light of man:pl'], '1:5': ['light in darkness shine:pr', 'darkness it:a comprehend:neg:pa'], '1:6': ['from god send:psv:adj', 'kjv_john_baptist'], '1:7': ['for witness', 'of kjv_light_john testify:inf', 'all man:pl through he'], '1:8': ['that kjv_light_john be:neg:pa', 'testify:inf send:psv:pa'], '1:9': ['true kjv_light_john', 'every man who into world come:pr light:caus:pr'], '1:10': ['world by he make:psv:pa', 'world he:a know:neg:pa'], '1:11': ['to his/own', 'his/own he:a receive:neg:pa'], '1:12': ['receive:pa', 'son:pl of god become:inf power', 'his/name believe:pr'], '1:13': ['not of blood', 'nor of will of flesh', 'nor of will of man', 'of god bear:psv:pa'], '1:14': ['kjv_word_john flesh make:psv:pa', 'among wesg', 'wesg his/glory', 'only beget:psv:adj of father', 'grace and truth'], '1:15': ['i speak:pa', 'after i come:pr before i prefer:psv:pr', 'for before i be:pa'], '1:16': ['his/full:ev all wesg receive:perf', 'grace for grace'], '1:17': ['law by kjv_moses', 'grace and truth', 'kjv_jesus_matthew kjv_christ_title'], '1:18': ['no man at any time', 'only beget:psv:adj son', 'bosom of father', 'declare:perf'], '1:19': ['kjv_record_witness', 'priest:pl and kjv_levite:pl', 'kjv_jerusalem', 'thou who'], '1:20': ['confess:pa and deny:neg:pa but confess:pa', 'i kjv_christ_title be:neg:pr'], '1:21': ['kjv_elias_matthew', 'i be:neg:pr', 'that prophet', 'answer:pa no'], '1:22': ['wesg:a send:pa', 'answer give:may', 'thyself'], '1:23': ['i voice of person', 'kjv_wilderness', 'kjv_lord straight make:imp', 'kjv_esaias'], '1:24': ['send:psv:pa of kjv_pharisee:pl'], '1:25': ['kjv_baptize:pr', 'kjv_christ_title nor kjv_elias_matthew neither that prophet'], '1:26': ['i with water kjv_baptize:pr', 'among you person whom know:neg:pr'], '1:27': ['after i', 'before i', 'kjv_shoelatchet loose:inf', 'i worthy be:neg:pr'], '1:28': ['kjv_bethabara_john beyond kjv_jordan', 'kjv_baptize:pprog'], '1:29': ['next day', 'kjv_lamb of god', 'sin of world away take:pr'], '1:30': ['i say:pa', 'after i man', 'before i prefer:psv:pr', 'before i be:pa'], '1:31': ['i he:a know:neg:pa', 'kjv_israel manifest:psv:may', 'water kjv_baptize:cv'], '1:32': ['i spirit from heaven as dove', 'upon he remain:pa'], '1:33': ['i he:a know:neg:pa', 'he who i:a', 'to i say:pa', 'spirit descend:cv and on he remain:cv', 'holy spirit'], '1:34': ['i see:pa and testify:pa', 'son of god'], '1:35': ['next day', 'two of his/disciple:pl'], '1:36': ['kjv_lamb of god behold:imp:excl'], '1:37': ['two disciple:pl', 'they:du kjv_jesus_matthew follow:pa'], '1:38': ['they:du follow:cv', 'what you:du seek:pr:q', 'kjv_rabbi', 'interpret:psv:cv master', 'where thou dwell:pr'], '1:39': ['they:du', 'come:imp and see:imp', 'about ten:ord hour'], '1:40': ['one_num of two', 'kjv_andrew_disciple', 'kjv_simon_peter kjv_peter_disciple'], '1:41': ['first', 'his/own brother', 'we:du kjv_messias_john', 'interpret:psv:cv kjv_christ_title'], '1:42': ['son of kjv_jona_simon_father', 'kjv_cephas_john', 'interpret:ev stone'], '1:43': ['kjv_galilee', 'kjv_philip_apostle', 'ipl:a follow:imp'], '1:44': ['kjv_bethsaida', 'kjv_andrew_disciple and kjv_peter_disciple'], '1:45': ['kjv_nathanael_john', 'wesg', 'kjv_moses in law and prophet:pl', 'kjv_nazareth son of kjv_joseph_mary'], '1:46': ['kjv_nazareth any good thing come:can:q', 'come:imp and see:imp'], '1:47': ['kjv_israelite', 'no kjv_guile', 'behold:imp:excl'], '1:48': ['i:a know:pr:q', 'before kjv_philip_apostle', 'under fig kjv_tree', 'ipl thee:a see:pa'], '1:49': ['kjv_rabbi', 'son of god', 'king of kjv_israel'], '1:50': ['ipl to thee say:pa ipl thee:a', 'believe:pr:q', 'greater thing:pl'], '1:51': ['truly truly ipl to you', 'heaven open:adj', 'upon son of man up go:cv and descend:cv'], '2:1': ['third day', 'kjv_cana_john of kjv_galilee', 'mother'], '2:2': ['kjv_jesus_matthew and his/disciple:pl', 'marriage call:psv:pa'], '2:3': ['wine lack:pa', 'wine have:neg:pr'], '2:4': ['woman what ipl with thee', 'mypl/hour yet come:neg:perf'], '2:5': ['to servant:pl', 'whatever', 'it:a do:imp'], '2:6': ['six kjv_waterpot_john:pl of stone', 'purify:ev of kjv_jew:pl', 'each two or three kjv_firkin_source:pl'], '2:7': ['with water fill:imp', 'to brim'], '2:8': ['out draw:imp', 'ruler of feast carry:imp', 'carry:pa'], '2:9': ['water which wine make:psv:pp', 'know:neg:pa', 'servant:pl who water draw:pa know:pa', 'kjv_bridegroom'], '2:10': ['beginning good wine', 'well drink:perf then worse', 'until now keep:perf'], '2:11': ['beginning of miracle:pl', 'kjv_cana_john', 'glory manifest:pa', 'disciple:pl on he believe:pa'], '2:12': ['kjv_capernaum', 'his/mother and his/brother:pl and his/disciple:pl', 'not many day:pl'], '2:13': ['kjv_passover', 'kjv_jerusalem up go:pa'], '2:14': ['ox:pl and sheep and dove:pl', 'money exchange:ag:pl sit:cv'], '2:15': ['small kjv_cord:pl kjv_scourge_lash', 'all they out of kjv_temple', 'sheep and ox:pl', 'money out pour:pa', 'kjv_table_furniture:pl kjv_overthrow:pa'], '2:16': ['dove:pl sell:pa', 'house of mypl/father', 'house of trade:ev make:neg:imp'], '2:17': ['disciple:pl remember:pa', 'write:psv:pp kjv_zeal of thine/house i:a up eat:perf'], '2:18': ['what sign to wesg', 'these thing:pl do:pr:q'], '2:19': ['kjv_temple destroy:imp', 'three day:pl ipl it:a up raise:fu'], '2:20': ['three+twelve and ten year:pl', 'build:psv:pprog', 'three day:pl'], '2:21': ['kjv_temple of his/body'], '2:22': ['from dead person:pl rise:pp', 'remember:pa', 'writing and word', 'believe:pa'], '2:23': ['kjv_jerusalem at kjv_passover', 'many on his/name', 'miracle:pl'], '2:24': ['himself to they entrust:neg:pa', 'all man:pl know:pa'], '2:25': ['testify:should need:neg:pa', 'what in man be:pa know:pa']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('kjv_word_john with god be:pa and kjv_word_john god be:pa',cases['1-1']['analysis'])
  self.assertIn('among wesg dwell:pa and wesg',cases['1-14']['analysis'])
  self.assertIn('i kjv_christ_title be:neg:pr',cases['1-20']['analysis'])
  self.assertIn('we:du kjv_messias_john',cases['1-41']['analysis'])
  self.assertIn('wesg he of whom',cases['1-45']['analysis'])
  self.assertIn('truly truly ipl to you',cases['1-51']['analysis'])
  self.assertIn('each two or three kjv_firkin_source:pl',cases['2-6']['analysis'])
  self.assertIn('kjv_zeal of thine/house i:a',cases['2-17']['analysis'])
  self.assertIn('three+twelve and ten year:pl',cases['2-20']['analysis'])
  self.assertIn('himself to they entrust:neg:pa',cases['2-24']['analysis'])
  for key in ('kjv_word_john','kjv_light_john'):self.assertEqual(lang.word(key)[0],lang.maxima(lang.lexicon[key]['form']))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),10)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
